import { render } from '@solidjs/web';
import { createSignal, createEffect, flush } from 'solid-js';

function App() {
  const [firstName, setFirstName] = createSignal('John');
  const [lastName, setLastName] = createSignal('Smith');
  const fullName = () => `${firstName()} ${lastName()}`;
  createEffect(fullName, (name) => console.log('Full name:', name));
  function updateNames() {
    setFirstName((name) => name + 'n');
    setLastName((name) => name + '!');
    console.log('Before flush:', fullName());
    // Flush here to make the new values visible to the next imperative read.
    console.log('After flush:', fullName());
  }
  return <button onClick={updateNames}>My name is {fullName()}</button>;
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal, createEffect, flush } from 'solid-js';

function App() {
  const [firstName, setFirstName] = createSignal('John');
  const [lastName, setLastName] = createSignal('Smith');
  const fullName = () => `${firstName()} ${lastName()}`;
  createEffect(fullName, (name) => console.log('Full name:', name));
  function updateNames() {
    setFirstName((name) => name + 'n');
    setLastName((name) => name + '!');
    console.log('Before flush:', fullName());
    flush();
    console.log('After flush:', fullName());
  }
  return <button onClick={updateNames}>My name is {fullName()}</button>;
}

render(() => <App />, document.getElementById('app'));
